python3 - << 'EOF'
import pandas as pd
import numpy as np

train = pd.read_csv('/work/b3_te_zt900_train.csv')
pool = pd.read_csv('/work/b3_te_zt900_pool.csv')
feats = [c for c in train.columns if c != 'target']

print("=== Train with S>0 ===")
for i, r in train[train['S']>0].sort_values('target', ascending=False).iterrows():
    nz = {c: round(r[c],4) for c in feats if r[c]>1e-8}
    print(f"  zT={r['target']:.3f} {nz}")

print("\n=== All pool compositions for remaining interesting ===")
for cid in ['c008','c021','c012','c086','c057','c078','c035','c077','c034']:
    row = pool[pool.candidate_id==cid].iloc[0]
    nz = {c: round(float(row[c]),4) for c in feats if row[c]>1e-8}
    print(f"{cid}: {nz}")

print("\n=== Train Co-Zr-Bi family ===")
m = (train['Co']>0.2)&(train['Zr']>0.2)&(train['Bi']>0.1)
for i, r in train[m].sort_values('target', ascending=False).iterrows():
    nz = {c: round(r[c],4) for c in feats if r[c]>1e-8}
    print(f"  zT={r['target']:.3f} {nz}")

print("\n=== Train Ni-Sn-Hf family ===")
m = (train['Ni']>0.2)&(train['Sn']>0.2)&(train['Hf']>0.05)
for i, r in train[m].sort_values('target', ascending=False).iterrows():
    nz = {c: round(r[c],4) for c in feats if r[c]>1e-8}
    print(f"  zT={r['target']:.3f} {nz}")

print("\n=== Train Fe-Sb-Nb family ===")
m = (train['Fe']>0.2)&(train['Sb']>0.2)&(train['Nb']>0.1)
print(f"n={m.sum()} mean={train.loc[m,'target'].mean():.3f} max={train.loc[m,'target'].max():.3f}")
for i, r in train[m].nlargest(8, 'target').iterrows():
    nz = {c: round(r[c],4) for c in feats if r[c]>1e-8}
    print(f"  zT={r['target']:.3f} {nz}")
